import { useEffect, useState } from 'react';
import { VisionCamera } from '../../VisionCamera';
export function useCameraSession({ enableMultiCamSupport, }) {
    const [session, setSession] = useState();
    // session creation
    useEffect(() => {
        let isCanceled = false;
        const load = async () => {
            const s = await VisionCamera.createCameraSession(enableMultiCamSupport);
            if (isCanceled) {
                s.dispose();
                return;
            }
            setSession(s);
        };
        load();
        return () => {
            isCanceled = true;
        };
    }, [enableMultiCamSupport]);
    // session teardown
    useEffect(() => {
        return () => {
            // remove all connections
            session?.stop();
            session?.configure([]);
        };
    }, [session]);
    return session;
}
